sp_widget.client_script:
api.controller = function($timeout) {

    var c = this;

    c.properties = [];
    //c.selectedTenants = [];

    c.$onInit = function() {

        c.server.get({
            action: "loadProperties"
        }).then(function(response) {

            c.properties = response.data.properties || [];
            //c.selectedTenants = response.data.selectedTenants || [];

        });

    };

    c.openProperty = function(sysId) {

        var url = "/now/nav/ui/classic/params/target/system_properties_ui.do%3Fsysparm_title%3DSettings%26sysparm_category%3DHP%2520WXP%2520AM%2520Application%2520Settings%26sysparm_domain_restore%3Dfalse%26sysparm_stack%3Dno";

        top.location.href = url;
    };

    c.saveProperties = function() {

        c.server.get({
            action: "saveProperties",
            properties: c.properties
        }).then(function() {

            c.showSuccess = true;

            $timeout(function() {
                c.showSuccess = false;
            }, 5000);

        });

    };

};

sp_widget.css:
.section {
  display: none;
}

.am-card {
  position: relative;
  background: #ffffff;
  border: 2px solid #e5e7eb !important;
  border-radius: 10px;
  box-shadow: 0 2px 6px rgba(0,0,0,0.05);
  margin-bottom: 20px;
}



.am-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 14px;
  font-size: 16px;
  font-weight: 600;
  color: #111827;
  background: #f9fafb;
  border-bottom: 1px solid #e5e7eb;
}


.am-header-text {
  flex: 1;
}


.am-header-actions {
  display: flex;
  gap: 8px;
  margin-left: 16px;
}


.am-subtitle {
  color: #64748b;
  font-size: 13px;
  margin: 0 0 16px 0;
}



.am-card-body {
  padding: 20px;
}



.am-field label {
  display: block;
  font-size: 13px;
  color: #6b7280;
  margin-bottom: 6px;
}



.form-control[readonly] {
  background: #f3f4f6;
  cursor: not-allowed;
  color: #4b5563;
}


.am-link-btn {
  padding-left: 0;
  margin-top: 6px;
  font-size: 12px;
}

.am-card {
    position: relative;
}

.am-toast {
    position: absolute;
    top: 15px;
    left: 50%;
    transform: translateX(-50%);
    z-index: 1000;

    background: #E7F6EC;
  	border: 1px solid #9FE0B5;
    color: #006B50;
    padding: 12px 20px;
    border-radius: 6px;
    font-weight: 600;
    box-shadow: 0 2px 8px rgba(0,0,0,0.2);
}

sp_widget.script:
(function() {

    var action = input && input.action;

    // The only settings this screen may read or write.
    var propertyNames = [
        "x_hpws_wrkfrcexpam.api.fastn.api.key",
        "x_hpws_wrkfrcexpam.fastn.space.id",
        "x_hpws_wrkfrcexpam.fastn_api_baseurl",
        //"x_hpws_wrkfrcexpam.tenants",
       // "x_hpws_wrkfrcexpam.tenant.type"
    ];

    if (action == "loadProperties") {

        data.properties = [];

        propertyNames.forEach(function(propName) {

            var propertyGr = new GlideRecordSecure('sys_properties');
            var description = '';
            var propSysId = '';

            propertyGr.addQuery('name', propName);
            propertyGr.setLimit(1);
            propertyGr.query();

            if (propertyGr.next()) {
                description = propertyGr.getValue('description') || '';
                propSysId = propertyGr.getUniqueValue();
            }

            data.properties.push({
                name: propName,
                description: description,
                sys_id: propSysId,
                value: gs.getProperty(propName, '')
            });

        });

        // Selected tenants come straight from the Tenant List (active rows).
       // data.selectedTenants = [];

    //     var tenantGr = new GlideRecordSecure('x_hpws_wrkfrcexpam_tenant_list');
    //     tenantGr.addQuery('active', true);
    //     tenantGr.orderBy('tenant');
    //     tenantGr.query();

    //     while (tenantGr.next()) {
    //         data.selectedTenants.push({
    //             tenant: tenantGr.getValue('tenant'),
    //             tenantid: tenantGr.getValue('tenantid')
    //         });
    //     }
     }

    if (action == "saveProperties") {

        (input.properties || []).forEach(function(prop) {

            // Ignore any name that is not one of the setup settings.
            if (propertyNames.indexOf(prop.name) === -1) return;

            gs.setProperty(prop.name, prop.value || '');
        });

    }

})();
